def orbit(r,c):
 return {(rr,cc) for rr,cc in [(r,c),(31-r,c),(r,31-c),(31-r,31-c)] if 0<=rr<30 and 0<=cc<30}
unresolved=[]
for r,c in masked:
 vals=[(x,y,g[x][y]) for x,y in orbit(r,c) if g[x][y]!=6]
 if not vals: unresolved.append((r,c,orbit(r,c)))
len(unresolved), unresolved[:15]

def fullorbit(r,c):
 trans=[(r,c),(31-r,c),(r,31-c),(31-r,31-c),(c,r),(31-c,r),(c,31-r),(31-c,31-r)]
 return {(rr,cc) for rr,cc in trans if 0<=rr<30 and 0<=cc<30}
un=[]
for r,c in masked:
 orb=fullorbit(r,c)
 vals=[(x,y,g[x][y]) for x,y in orb if g[x][y]!=6]
 if not vals: un.append((r,c,orb))
len(un), un[:30]

